// Controlled stage only. Never retires MSI, installs prerequisites, closes the app, or changes Codex settings.
public static class SafeStage {
 static readonly JsonSerializerOptions Json=new(){PropertyNameCaseInsensitive=true,WriteIndented=true};
 internal static string Member(string root,string relative){if(string.IsNullOrWhiteSpace(relative)||relative.Contains(':')||relative.Contains('\\')||relative.Split('/').Any(x=>x is "" or "." or ".."||x.EndsWith('.')||x.EndsWith(' ')))throw new IOException("Invalid release member");return MigrationStorage.Canonical(Path.Combine(root,relative));}
 internal static void ValidateRelease(StageRelease m){if(m.RootUpdaterSha256.Length!=64||!m.RootUpdaterSha256.All(Uri.IsHexDigit)||m.Schema!=1||m.PackageId!="CodexLightDesktop"||m.VelopackVersion!="1.3.39-g8d2844f"||m.Shortcuts!="None"||!Version.TryParse(m.Version,out var v)||v.Build>=900||m.Files.Length==0||m.PayloadFiles.Length==0)throw new IOException("Unapproved migration package identity");foreach(var list in new[]{m.Files,m.PayloadFiles}){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var f in list)if(!seen.Add(f.Path)||f.Bytes<0||f.Sha256.Length!=64||!f.Sha256.All(Uri.IsHexDigit))throw new IOException("Invalid manifest");}foreach(var required in new[]{m.Setup,m.Prerequisite,m.Prerequisite+".config",m.FullPackage})if(!m.Files.Any(x=>x.Path==required))throw new IOException("Required artifact absent");foreach(var required in new[]{"sq.version","CodexLight.exe","app/src/backend-health.mjs"})if(!m.PayloadFiles.Any(x=>x.Path==required))throw new IOException("Required payload absent");}
 internal static void VerifyFiles(string root,DataFile[] files,bool exact){var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var f in files){var p=Member(root,f.Path);if(!File.Exists(p)||new FileInfo(p).Length!=f.Bytes||MigrationCoordinator.Hash(p)!=f.Sha256.ToLowerInvariant())throw new IOException("Artifact verification failed: "+f.Path);paths.Add(p);}if(exact){void Walk(string d){foreach(var p in Directory.EnumerateFileSystemEntries(d)){MigrationStorage.Canonical(p);if(Directory.Exists(p))Walk(p);else if(!paths.Remove(p))throw new IOException("Unexpected installed payload: "+p);}}Walk(root);if(paths.Count!=0)throw new IOException("Payload missing");}}
 internal static void PackageIdentity(string payload,StageRelease m){var x=XDocument.Load(Path.Combine(payload,"sq.version"));string Field(string name)=>x.Descendants().Single(e=>e.Name.LocalName==name).Value;if(Field("id")!=m.PackageId||Field("version")!=m.Version||Field("shortcutLocations")!="None"||Field("mainExe")!="CodexLight.exe")throw new IOException("sq.version migration policy mismatch");}
 internal static void Idle(string oldRoot,string newRoot){string Q(string value)=>"'"+value.Replace("'","''")+"'";
var data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CodexLight");
var ps="$ErrorActionPreference='Stop';try{$roots=@("+Q(oldRoot)+","+Q(newRoot)+","+Q(data)+");$busy=@(Get-CimInstance Win32_Process | Where-Object { $_.Name -match '^(node|msedgewebview2|CodexLight)\\.exe$' } | Where-Object {$line=$_.CommandLine;if(!$line){$true}else{ @($roots | Where-Object {$line.IndexOf($_,[StringComparison]::OrdinalIgnoreCase) -ge 0}).Count -gt 0 }});if($busy.Count){exit 31};exit 0}catch{exit 32}";
var shell=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe");
if(Run(shell,"-NoProfile","-NonInteractive","-EncodedCommand",Convert.ToBase64String(System.Text.Encoding.Unicode.GetBytes(ps))).Code!=0)throw new IOException("Related backend/WebView process exists or process inventory uncertain");foreach(var p in Process.GetProcesses()){using(p){try{var path=p.MainModule?.FileName;if(path!=null&&(path.StartsWith(oldRoot+"\\",StringComparison.OrdinalIgnoreCase)||path.StartsWith(newRoot+"\\",StringComparison.OrdinalIgnoreCase)))throw new IOException("Process in installation root: "+p.Id);}catch(System.ComponentModel.Win32Exception){if(p.ProcessName.StartsWith("CodexLight",StringComparison.OrdinalIgnoreCase))throw new IOException("Cannot prove app process idle");}catch(InvalidOperationException){}}}}
 internal sealed record ProcessResult(int Code,string Output,string Error,int NativeExitCode,bool TimedOut);
 internal static ProcessResult Run(string exe,params string[] args){
  var si=new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};
  foreach(var a in args)si.ArgumentList.Add(a);
  using var p=Process.Start(si)??throw new IOException("Start failed");
  var output=ReadBounded(p.StandardOutput);var error=ReadBounded(p.StandardError);
  bool timedOut=!p.WaitForExit(180000);
  if(timedOut){Console.Error.WriteLine("Child still running; retaining exclusion locks until it exits. No force stop.");p.WaitForExit();}
  Task.WaitAll(output,error);
  return new(timedOut?-10001:p.ExitCode,output.Result,error.Result,p.ExitCode,timedOut);
 }
 static async Task<string> ReadBounded(StreamReader reader){var text=new System.Text.StringBuilder();var buffer=new char[4096];bool truncated=false;int n;while((n=await reader.ReadAsync(buffer,0,buffer.Length))>0){int keep=Math.Min(n,Math.Max(0,65536-text.Length));text.Append(buffer,0,keep);if(keep<n)truncated=true;}if(truncated)text.Append("\n[diagnostic output truncated after 65536 characters; stream drained]");return text.ToString();}
 internal static void Registration(string root,StageRelease m){using var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\"+m.PackageId);if(key==null||!string.Equals(MigrationStorage.Canonical((string?)key.GetValue("InstallLocation")??""),root,StringComparison.OrdinalIgnoreCase)||(string?)key.GetValue("DisplayVersion")!=m.Version)throw new IOException("New registration mismatch");}
 public static void Execute(string manifestPath,string trustedHash,string trustedSetupHash,bool stage,bool sameVersion,bool tasksConfirmed){
  manifestPath=MigrationStorage.Canonical(manifestPath);if(trustedHash.Length!=64||MigrationCoordinator.Hash(manifestPath)!=trustedHash.ToLowerInvariant())throw new IOException("Trusted release manifest hash mismatch");
  var m=JsonSerializer.Deserialize<StageRelease>(File.ReadAllText(manifestPath),Json)??throw new IOException("Manifest missing");ValidateRelease(m);var release=Path.GetDirectoryName(manifestPath)!;VerifyFiles(release,m.Files,false);var payload=Member(release,m.PayloadDirectory);VerifyFiles(payload,m.PayloadFiles,true);PackageIdentity(payload,m);if(trustedSetupHash.Length!=64||MigrationCoordinator.Hash(Member(release,m.Setup))!=trustedSetupHash.ToLowerInvariant())throw new IOException("Trusted Setup hash mismatch");var setupBytes=File.ReadAllBytes(Member(release,m.Setup));var packageBytes=File.ReadAllBytes(Member(release,m.FullPackage));if(setupBytes.Length<2||setupBytes[0]!=77||setupBytes[1]!=90||setupBytes.AsSpan().IndexOf(packageBytes)<0)throw new IOException("Setup does not embed exact verified full package");using(var zip=ZipFile.OpenRead(Member(release,m.FullPackage))){var entry=zip.GetEntry("lib/app/sq.version")??throw new IOException("Package identity absent");foreach(var f in m.PayloadFiles){var member=zip.GetEntry("lib/app/"+f.Path)??throw new IOException("Payload absent from full package");using var memberStream=member.Open();if(member.Length!=f.Bytes||Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(memberStream)).ToLowerInvariant()!=f.Sha256.ToLowerInvariant())throw new IOException("Payload differs from full package");}using var input=entry.Open();var metadata=XDocument.Load(input);string F(string n)=>metadata.Descendants().Single(e=>e.Name.LocalName==n).Value;if(F("id")!=m.PackageId||F("version")!=m.Version||F("shortcutLocations")!="None")throw new IOException("Full package identity mismatch");var stub=zip.GetEntry("lib/app/Codex Light_ExecutionStub.exe")??throw new IOException("Execution stub absent");using(var stubStream=stub.Open()){if(m.RootStubPath!="Codex Light.exe"||Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(stubStream)).ToLowerInvariant()!=m.RootStubSha256.ToLowerInvariant())throw new IOException("Root stub manifest mismatch");}var update=zip.GetEntry("lib/app/Squirrel.exe")??throw new IOException("Root updater missing");using var stream=update.Open();if(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(stream)).ToLowerInvariant()!=m.RootUpdaterSha256.ToLowerInvariant())throw new IOException("Root updater manifest mismatch");}
  var old=MsiProbe.ReadCurrentUser();MigrationStorage.Canonical(old.SourceMsi);var local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);var destination=MigrationStorage.Canonical(Path.Combine(local,"CodexLightDesktop"));var oldRoot=MigrationStorage.Canonical(old.InstallRoot);var dataRoot=MigrationStorage.Canonical(Path.Combine(local,"CodexLight"));
  foreach(var pair in new[]{(oldRoot,destination),(dataRoot,destination),(dataRoot,oldRoot)})if(pair.Item1.Equals(pair.Item2,StringComparison.OrdinalIgnoreCase)||pair.Item1.StartsWith(pair.Item2+"\\",StringComparison.OrdinalIgnoreCase)||pair.Item2.StartsWith(pair.Item1+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("Roots overlap");
  int comparison=Version.Parse(m.Version).CompareTo(Version.Parse(old.Version));if(comparison<0||(comparison==0&&!sameVersion))throw new IOException("Downgrade or unapproved same-version format migration");
  Console.WriteLine(JsonSerializer.Serialize(new{Mode=stage?"Stage":"Inspect",Old=old,Destination=destination,Target=m.Version,ManifestSha256=trustedHash,RetireEnabled=false},Json));if(!stage)return;
  if(!tasksConfirmed)throw new IOException("Explicit confirmation of completed tasks is required; process absence alone is not task proof");string sid=WindowsIdentity.GetCurrent().User?.Value??throw new IOException("SID missing");var scope=new NamedWaitHandleOptions{CurrentUserOnly=true,CurrentSessionOnly=true};using var desktop=new Mutex(true,"CodexLight.Desktop."+sid,scope,out bool first);if(!first)throw new IOException("Desktop mutex exists; exit app normally before staging");
  try{using var locks=MigrationStorage.AcquireInstallRoots(oldRoot,destination);Idle(oldRoot,destination);if(Directory.Exists(destination)||File.Exists(destination))throw new IOException("Destination must be absent");using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\CodexLightDesktop"))if(key!=null)throw new IOException("Destination registration exists");
   if(MsiProbe.ReadCurrentUser()!=old)throw new IOException("MSI inventory changed");
   // Validate installed runtime prerequisites without permitting Setup to download/install them.
   if(!Directory.Exists(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"dotnet","shared","Microsoft.WindowsDesktop.App"))||!Directory.EnumerateDirectories(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"dotnet","shared","Microsoft.WindowsDesktop.App")).Any(p=>Path.GetFileName(p).StartsWith("10.")))throw new IOException(".NET10 Desktop prerequisite unavailable");
   var edge=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"Microsoft","EdgeWebView","Application");if(!Directory.Exists(edge)||!Directory.EnumerateDirectories(edge).Any(p=>File.Exists(Path.Combine(p,"msedgewebview2.exe"))))throw new IOException("WebView2 prerequisite unavailable");
   if(Run(Member(release,m.Prerequisite),"--check-node",payload).Code!=0)throw new IOException("Node prerequisite unavailable");
   var preflight=Run(Path.Combine(payload,"CodexLight.exe"),"--backend-health-check");if(preflight.Code!=0)throw new IOException("Verified payload native/backend prerequisite preflight failed");using(var preflightJson=JsonDocument.Parse(preflight.Output)){var h=preflightJson.RootElement;if(!Version.TryParse(h.GetProperty("webViewVersion").GetString(),out _)||!Version.TryParse(h.GetProperty("dotnetVersion").GetString(),out var dotnet)||dotnet.Major!=10||!h.GetProperty("ok").GetBoolean()||h.GetProperty("scope").GetString()!="native-and-isolated-demo-backend"||h.GetProperty("realAccountVerified").GetBoolean()||!h.GetProperty("gracefulShutdown").GetBoolean()||h.GetProperty("backendVersion").GetString()!=m.Version)throw new IOException("Preflight health evidence mismatch");}
   var data=MigrationStorage.CaptureApplicationData();long required=MigrationStorage.RequiredBytes(data,m.PayloadFiles.Sum(f=>f.Bytes),m.Files.Sum(f=>f.Bytes),new FileInfo(old.SourceMsi).Length);if(new DriveInfo(Path.GetPathRoot(local)!).AvailableFreeSpace<required)throw new IOException("Insufficient stage/recovery volume space");if(Path.GetPathRoot(Path.GetTempPath())!=Path.GetPathRoot(local)&&new DriveInfo(Path.GetPathRoot(Path.GetTempPath())!).AvailableFreeSpace<required)throw new IOException("Insufficient temp volume space");
   var recovery=MigrationStorage.Canonical(Path.Combine(local,"CodexLightMigration",Guid.NewGuid().ToString("N")));Directory.CreateDirectory(recovery);string receipt=Path.Combine(recovery,"receipt.json"),backup=Path.Combine(recovery,"data");
   void Journal(string phase,string detail)=>MigrationStorage.AtomicReceipt(receipt,new{Phase=phase,Detail=detail,Legacy=old,NewRoot=destination,ManifestSha256=trustedHash,SetupSha256=trustedSetupHash,Target=m.Version,SameVersion=comparison==0,Recovery=recovery,RetireEnabled=false});
   Journal("Preparing","No installer started");try{MigrationStorage.CopySnapshot(data,backup);File.Copy(old.SourceMsi,Path.Combine(recovery,"legacy.msi"));if(MigrationCoordinator.Hash(Path.Combine(recovery,"legacy.msi"))!=old.SourceSha256)throw new IOException("MSI backup mismatch");MigrationStorage.VerifySnapshot(data,backup);VerifyFiles(release,m.Files,false);Idle(oldRoot,destination);if(MsiProbe.ReadCurrentUser()!=old)throw new IOException("MSI changed before stage");Journal("Staging","Old MSI preserved; installer outcome may be uncertain");
    var result=Run(Member(release,m.Setup),"--silent","--installto",destination,"--log",Path.Combine(recovery,"setup.log"));MigrationStorage.AtomicReceipt(Path.Combine(recovery,"setup-process.json"),new{result.Code,result.NativeExitCode,result.TimedOut,Stdout=result.Output,Stderr=result.Error,SetupSha256=trustedSetupHash,ExpectedLog=Path.Combine(recovery,"setup.log"),ExpectedLogExists=File.Exists(Path.Combine(recovery,"setup.log"))});if(result.Code!=0)throw new IOException("Setup returned "+result.NativeExitCode+(result.TimedOut?" after timeout":"")+"; inspect setup-process.json (stdout/stderr preserved)");
    if(MigrationCoordinator.Hash(Path.Combine(destination,"Update.exe"))!=m.RootUpdaterSha256.ToLowerInvariant())throw new IOException("Installed root updater mismatch");if(m.RootStubPath!="Codex Light.exe"||m.RootStubSha256.Length!=64||MigrationCoordinator.Hash(Member(destination,m.RootStubPath))!=m.RootStubSha256.ToLowerInvariant())throw new IOException("Root execution stub mismatch");var current=Path.Combine(destination,"current");VerifyFiles(current,m.PayloadFiles,true);PackageIdentity(current,m);Registration(destination,m);
    var health=Run(Path.Combine(current,"CodexLight.exe"),"--backend-health-check");if(health.Code!=0)throw new IOException("Backend health failed");using var doc=JsonDocument.Parse(health.Output);var h=doc.RootElement;if(!Version.TryParse(h.GetProperty("webViewVersion").GetString(),out _)||!Version.TryParse(h.GetProperty("dotnetVersion").GetString(),out var dotnet)||dotnet.Major!=10||!h.GetProperty("ok").GetBoolean()||h.GetProperty("scope").GetString()!="native-and-isolated-demo-backend"||h.GetProperty("realAccountVerified").GetBoolean()||!h.GetProperty("gracefulShutdown").GetBoolean()||h.GetProperty("backendVersion").GetString()!=m.Version)throw new IOException("Unexpected health evidence");
    if(JsonSerializer.Serialize(MigrationStorage.CaptureApplicationData())!=JsonSerializer.Serialize(data)||MsiProbe.ReadCurrentUser()!=old)throw new IOException("Old MSI or protected data changed");MigrationStorage.VerifySnapshot(data,backup);Journal("StagedOldPreserved","Component health passed; separate GUI observation and explicit retire required");Console.WriteLine(receipt);
   }catch(Exception ex){Journal("RecoveryRequired",ex.Message);throw;}
  }finally{desktop.ReleaseMutex();}
 }
